package com.oguzguven.portfolio.settings;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/settings") public class SiteSettingsController{private final SiteSettingsService service;public SiteSettingsController(SiteSettingsService service){this.service=service;}@GetMapping public SiteSettingsResponse get(){return service.get();}@PutMapping public SiteSettingsResponse update(@Valid @RequestBody SiteSettingsRequest request){return service.update(request);}}
